import {getProperty,properties,money,state} from './data.js';
import {header,footer,photo,icon,button,specs,price,card} from './ui.js';
import {mapMarkup} from './public.js';
export function propertyPage(id,signature=false){const p=getProperty(id);return `${header()}<main id="main" class="${signature?'signature-page':'essential-page'}">${signature?`<section class="signature-hero">${photo('cinematic','signature-photo')}<div class="signature-shade"></div><div class="signature-copy"><span class="eyebrow">${p.region.toUpperCase()} · COLEÇÃO SIGNATURE</span><h1>${p.name==='Residencial Neo Carrão'?'Residencial<br>Neo Carrão':p.name}</h1><span class="yellow-rule"></span><p>Conforto, arquitetura e um novo<br>ritmo de vida na Zona Leste.</p>${specs(p)}<span class="price-label">${p.mode==='Alugar'?'Aluguel':'Venda'}</span><strong class="price">${price(p)}</strong><div class="button-row"><button class="btn light" data-schedule="${p.id}">${icon('calendar')}Agendar visita</button><button class="btn ghost" data-contact="${p.id}">Conversar sobre o imóvel${icon('arrow')}</button></div><div class="presentation-controls"><span id="slide-count">01 — 04</span><div class="slide-bars"><i class="active"></i><i></i><i></i><i></i></div><button class="round" data-slide="-1" aria-label="Foto anterior">${icon('back')}</button><button class="round" data-slide="1" aria-label="Próxima foto">${icon('arrow')}</button></div></div><div class="signature-caption">SIGNATURE / ${p.id}<span>FOTOGRAFIA ILUSTRATIVA</span></div></section>`:`<div class="section property-top"><div class="breadcrumb"><a href="#/busca">Imóveis</a><span>/</span>${p.region}<span>/</span>${p.id}</div><div class="section-heading"><div><span class="eyebrow">${p.region.toUpperCase()} · ZONA LESTE</span><h1>${p.name}</h1><p>Um espaço para viver seus próximos capítulos.</p></div><button class="btn outline ${state.favorites.includes(p.id)?'active':''}" data-favorite="${p.id}" aria-pressed="${state.favorites.includes(p.id)}">${icon('heart')}<span>${state.favorites.includes(p.id)?'Imóvel salvo':'Salvar imóvel'}</span></button></div><div class="essential-gallery"><button data-gallery="${p.photo}" aria-label="Ampliar fotografia principal">${photo(p.photo)}</button><button data-gallery="living2" aria-label="Ampliar fotografia da sala">${photo('living2')}</button><button data-gallery="bedroom" aria-label="Ampliar fotografia do quarto">${photo('bedroom')}</button><button class="gallery-all btn light" data-gallery="${p.photo}">${icon('grid')}Ver galeria</button></div></div>`}<div class="territory-strip"><div>${icon('train')}<span><b>Mobilidade no radar</b>Explore as conexões da região</span></div><div>${icon('building')}<span><b>Vida de bairro</b>Serviços e comércio no entorno</span></div><div>${icon('sound')}<span><b>Ruído percebido: ${p.noise}</b>Avaliação demonstrativa</span></div><div>${icon('info')}<span><b>Contexto para escolher</b>Informações com origem e data</span></div></div>${signature?`<section class="architecture-story">${photo('facade')}<div><span class="eyebrow">ARQUITETURA PARA O DIA A DIA</span><h2>O extraordinário<br>mora nos detalhes.</h2><span class="yellow-rule"></span><p>Luz que atravessa os espaços. Materiais que acolhem. Uma nova perspectiva sobre a vida urbana.</p><p>Uma composição contemporânea para os momentos que fazem de uma casa o seu lugar.</p></div></section><section class="section editorial-gallery"><div class="section-heading"><span class="eyebrow">UM OLHAR MAIS DE PERTO</span><span>01 / 04 — GALERIA ILUSTRATIVA</span></div><div class="gallery-grid">${['living2','bedroom','kitchen','balcony'].map(k=>`<button data-gallery="${k}" aria-label="Ampliar fotografia">${photo(k)}</button>`).join('')}</div></section>`:''}<section class="section property-details"><div><span class="eyebrow">O ESPAÇO</span><h2>Feito para o seu ritmo.</h2>${specs(p)}<p>Este imóvel fictício de ${p.area} m², em ${p.region}, reúne ${p.beds} dormitórios e ambientes integrados em uma proposta contemporânea. A iluminação natural e a distribuição dos espaços convidam a imaginar uma nova rotina.</p><p>Fotografias e características são ilustrativas e compõem uma demonstração de produto, sem correspondência com uma unidade disponível.</p><div class="amenities">${['Ambientes integrados','Iluminação natural','Varanda','Cozinha planejada'].map(x=>`<span>${icon('check')}${x}</span>`).join('')}</div><details class="territorial-details" open><summary>Avaliação territorial${icon('chevron')}</summary><div class="territorial-grid"><div><small>RUÍDO PERCEBIDO</small><b>${p.noise}</b><span class="status warm">Relato ilustrativo</span></div><div><small>PERÍODO OBSERVADO</small><b>Dias úteis · tarde</b><span>Observação simulada</span></div><div><small>ORIGEM E RESPONSÁVEL</small><b>Visita do corretor · Pedro</b><span>Registro fictício · 10/11/2026</span></div><div><small>TOPOGRAFIA E SERVIÇOS</small><b>Não verificados</b><span>Confirmar em visita presencial</span></div></div></details><details class="territorial-details"><summary>Planta ilustrativa${icon('chevron')}</summary><div class="floor-plan"><span>SALA / COZINHA</span><span>DORMITÓRIO 01</span><span>VARANDA</span><span>DORMITÓRIO 02</span><span>BANHO</span></div><p class="micro">Diagrama conceitual, sem escala e sem valor técnico. Não representa uma planta real.</p></details><div class="local-map"><h3>Um olhar para ${p.region}</h3>${mapMarkup([p],p.id)}</div></div><aside class="contact-card"><span class="eyebrow">${p.mode==='Alugar'?'ALUGUEL MENSAL':'VALOR DE VENDA'}</span><strong class="price">${price(p)}</strong><div class="cost-row"><span>Condomínio</span><b>${money(p.fee)}/mês</b></div><div class="cost-row"><span>IPTU</span><b>${money(p.tax)}/mês</b></div>${p.mode==='Alugar'?`<div class="cost-row total"><span>Total estimado</span><b>${money(p.price+p.fee+p.tax)}/mês</b></div>`:''}<button class="btn dark full" data-schedule="${p.id}">${icon('calendar')}Agendar uma visita</button><button class="btn outline full" data-contact="${p.id}">Tenho interesse${icon('arrow')}</button><p class="micro">Simulação sem envio de mensagens.<br>Nenhum dado pessoal será solicitado.</p><div class="agent"><span class="avatar">PM</span><span><b>Equipe Property Match</b><small>Atendimento demonstrativo</small></span></div><a class="text-link" href="#/${signature?'imovel':'signature'}/${p.id}">Ver apresentação ${signature?'Essencial':'Signature'}${icon('arrow')}</a><span class="demo-label">IMÓVEL FICTÍCIO · ${p.id}</span></aside></section><section class="section"><div class="section-heading"><div><span class="eyebrow">OUTRAS POSSIBILIDADES</span><h2>Seu lugar pode estar aqui.</h2></div></div><div class="property-grid three">${properties.filter(x=>x.id!==p.id).slice(0,3).map(x=>card(x)).join('')}</div></section></main>${footer()}`;}
